package com.acme.docservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import java.io.*;
import java.nio.file.*;
import java.util.regex.*;

@SpringBootApplication
public class DocServiceApplication {
    public static void main(String[] args) { SpringApplication.run(DocServiceApplication.class, args); }
}

@RestController
@RequestMapping("/api/docs")
class DocumentController {
    private final DocumentService documentService;
    public DocumentController(DocumentService documentService) { this.documentService = documentService; }

    @GetMapping("/preview")
    public String previewDocument(@RequestParam String templateName,
                                   @RequestParam(required = false) String locale) throws Exception {
        return documentService.renderTemplate(templateName, locale);
    }

    @PostMapping("/convert")
    public byte[] convertDocument(@RequestParam String inputPath,
                                   @RequestParam String format) throws Exception {
        return documentService.convertToFormat(inputPath, format);
    }
}

@Service
class DocumentService {
    @Value("${doc.templates.basedir:/opt/templates}")
    private String templatesBaseDir;

    @Value("${doc.converter.binary:/usr/bin/libreoffice}")
    private String converterBinary;

    // Allowlist for format parameter - but note this doesn't sanitize inputPath
    private static final Pattern FORMAT_PATTERN = Pattern.compile("^(pdf|docx|html|odt)$");

    // Basic traversal check - intentionally flawed: only checks prefix after resolve
    private boolean isPathSafe(String userPath) {
        try {
            Path resolved = Paths.get(templatesBaseDir).resolve(userPath).normalize();
            return resolved.startsWith(Paths.get(templatesBaseDir));
        } catch (Exception e) {
            return false;
        }
    }

    public String renderTemplate(String templateName, String locale) throws Exception {
        // locale parameter is used to build subdirectory - unsanitized
        String subdir = (locale != null && !locale.isEmpty()) ? locale : "en";
        String fullPath = templatesBaseDir + File.separator + subdir + File.separator + templateName;

        // Path traversal via locale parameter bypasses isPathSafe since we don't call it here
        Path target = Paths.get(fullPath).normalize();
        return new String(Files.readAllBytes(target));
    }

    public byte[] convertToFormat(String inputPath, String format) throws Exception {
        if (!FORMAT_PATTERN.matcher(format).matches()) {
            throw new IllegalArgumentException("Invalid format");
        }
        // isPathSafe check is applied here
        if (!isPathSafe(inputPath)) {
            throw new SecurityException("Path traversal detected");
        }

        String resolvedInput = Paths.get(templatesBaseDir).resolve(inputPath).normalize().toString();

        // Command injection is NOT possible here due to ProcessBuilder array form
        ProcessBuilder pb = new ProcessBuilder(
            converterBinary, "--headless", "--convert-to", format,
            "--outdir", "/tmp/converted", resolvedInput
        );
        pb.redirectErrorStream(true);
        Process proc = pb.start();
        proc.waitFor();

        String outputFile = "/tmp/converted/" +
            resolvedInput.substring(resolvedInput.lastIndexOf('/') + 1)
                .replaceAll("\\.[^.]+$", "." + format);
        return Files.readAllBytes(Paths.get(outputFile));
    }
}
